"use client";

import { useState, useRef, useEffect } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";

export default function Home() {
  const [conversations, setConversations] = useState([]);
  const [activeChat, setActiveChat] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [imageLoading, setImageLoading] = useState(false);
  const [user, setUser] = useState(null);

  const abortControllerRef = useRef(null);
  const router = useRouter();

  // Auth check & User session load
  useEffect(() => {
    const checkUser = async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();

      if (!user) {
        router.push("/login");
      } else {
        setUser(user);
        fetchConversations(user.id);
      }
    };
    checkUser();
  }, [router]);

  // Messages load jab active chat change ho
  useEffect(() => {
    if (activeChat) {
      fetchMessages(activeChat);
    } else {
      setMessages([]);
    }
  }, [activeChat]);

  const fetchConversations = async (userId) => {
    const { data } = await supabase
      .from("conversations")
      .select("*")
      .eq("user_id", userId)
      .order("created_at", { ascending: false });

    if (data) setConversations(data);
  };

  const fetchMessages = async (chatId) => {
    const { data } = await supabase
      .from("messages")
      .select("*")
      .eq("conversation_id", chatId)
      .order("created_at", { ascending: true });

    if (data) setMessages(data);
  };

  const createNewChat = async () => {
    if (!user) return;
    setActiveChat(null);
    setMessages([]);
  };

  const deleteConversation = async (e, id) => {
    e.stopPropagation();
    await supabase.from("conversations").delete().eq("id", id);
    setConversations(conversations.filter((c) => c.id !== id));
    if (activeChat === id) {
      setActiveChat(null);
      setMessages([]);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/login");
  };

  async function sendMessage(e) {
    e?.preventDefault();

    const text = input.trim();
    if (!text || loading || imageLoading) return;

    let chatId = activeChat;

    // Naya conversation create karein agar pehle se active chat na ho
    if (!chatId) {
      const { data } = await supabase
        .from("conversations")
        .insert({ user_id: user.id, title: text.slice(0, 30) })
        .select()
        .single();

      if (data) {
        chatId = data.id;
        setActiveChat(data.id);
        setConversations([data, ...conversations]);
      }
    }

    const next = [...messages, { role: "user", content: text }];
    setMessages(next);
    setInput("");
    setLoading(true);

    if (chatId) {
      await supabase.from("messages").insert({
        conversation_id: chatId,
        role: "user",
        content: text,
        type: "text",
      });
    }

    abortControllerRef.current = new AbortController();

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt: text }),
        signal: abortControllerRef.current.signal,
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || "Request failed");
      }

      if (!res.body) return;

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let assistantResponse = "";

      setMessages([...next, { role: "assistant", content: "" }]);

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        const textChunk = decoder.decode(value, { stream: true });
        assistantResponse += textChunk;

        setMessages((prev) => {
          const updated = [...prev];
          updated[updated.length - 1] = {
            role: "assistant",
            content: assistantResponse,
          };
          return updated;
        });
      }

      if (chatId) {
        await supabase.from("messages").insert({
          conversation_id: chatId,
          role: "assistant",
          content: assistantResponse,
          type: "text",
        });
      }
    } catch (err) {
      if (err.name === "AbortError") {
        setMessages((prev) => [
          ...prev.slice(0, -1),
          { role: "assistant", content: "Response stopped" },
        ]);
      } else {
        setMessages([
          ...next,
          {
            role: "assistant",
            content: "Error: " + err.message,
          },
        ]);
      }
    } finally {
      setLoading(false);
    }
  }

  async function generateImage(e) {
    e?.preventDefault();

    const text = input.trim();
    if (!text || loading || imageLoading) return;

    let chatId = activeChat;

    if (!chatId) {
      const { data } = await supabase
        .from("conversations")
        .insert({ user_id: user.id, title: "🖼️ " + text.slice(0, 25) })
        .select()
        .single();

      if (data) {
        chatId = data.id;
        setActiveChat(data.id);
        setConversations([data, ...conversations]);
      }
    }

    const next = [
      ...messages,
      {
        role: "user",
        content: "🖼️ Generate image: " + text,
      },
    ];

    setMessages(next);
    setInput("");
    setImageLoading(true);

    if (chatId) {
      await supabase.from("messages").insert({
        conversation_id: chatId,
        role: "user",
        content: "🖼️ Generate image: " + text,
        type: "text",
      });
    }

    abortControllerRef.current = new AbortController();

    try {
      const res = await fetch("/api/image", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt: text }),
        signal: abortControllerRef.current.signal,
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || "Image generation failed");
      }

      setMessages([
        ...next,
        {
          role: "assistant",
          type: "image",
          content: data.url || data.image,
        },
      ]);

      if (chatId) {
        await supabase.from("messages").insert({
          conversation_id: chatId,
          role: "assistant",
          content: data.url || data.image,
          type: "image",
        });
      }
    } catch (err) {
      if (err.name === "AbortError") {
        setMessages((prev) => [
          ...prev,
          { role: "assistant", content: "Response stopped" },
        ]);
      } else {
        setMessages([
          ...next,
          {
            role: "assistant",
            content: "Image Error: " + err.message,
          },
        ]);
      }
    } finally {
      setImageLoading(false);
    }
  }

  const stopResponse = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      setLoading(false);
      setImageLoading(false);
    }
  };

  return (
    <main className="shell">
      <aside className="sidebar">
        <button className="newChat" onClick={createNewChat}>
          ＋ New chat
        </button>

        <div className="brand">MY AI</div>

        <div className="conversationsList" style={{ flex: 1, overflowY: "auto" }}>
          {conversations.map((chat) => (
            <div
              key={chat.id}
              onClick={() => setActiveChat(chat.id)}
              className={`chatItem ${activeChat === chat.id ? "active" : ""}`}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                padding: "8px 12px",
                cursor: "pointer",
                borderRadius: "6px",
                marginBottom: "4px",
              }}
            >
              <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {chat.title}
              </span>
              <button
                onClick={(e) => deleteConversation(e, chat.id)}
                style={{ background: "none", border: "none", color: "#ff4d4d", cursor: "pointer" }}
              >
                ✕
              </button>
            </div>
          ))}
        </div>

        <button
          onClick={handleLogout}
          style={{
            padding: "8px",
            background: "#d9534f",
            color: "white",
            border: "none",
            borderRadius: "6px",
            cursor: "pointer",
            marginTop: "10px",
          }}
        >
          Logout
        </button>
      </aside>

      <section className="chat">
        <header className="topbar">
          <strong>My AI</strong>
          <span>GPT-4o Mini</span>
        </header>

        <div className="messages">
          {messages.length === 0 ? (
            <div className="welcome">
              <h1>How can I help?</h1>
              <p>Ask anything or generate an image.</p>
            </div>
          ) : (
            messages.map((m, i) => (
              <div className={"row " + m.role} key={i}>
                <div className="bubble">
                  {m.type === "image" ? (
                    <img
                      src={m.content}
                      alt="Generated image"
                      style={{
                        maxWidth: "100%",
                        width: "700px",
                        borderRadius: "14px",
                        display: "block",
                      }}
                    />
                  ) : (
                    <span style={{ whiteSpace: "pre-wrap" }}>{m.content}</span>
                  )}
                </div>
              </div>
            ))
          )}

          {(loading || imageLoading) && (
            <div className="row assistant">
              <div className="bubble">
                {imageLoading ? "Creating your image…" : "Thinking…"}
              </div>
            </div>
          )}
        </div>

        <form className="composer" onSubmit={sendMessage}>
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Message My AI…"
            disabled={loading || imageLoading}
          />

          <button
            type="button"
            onClick={generateImage}
            disabled={loading || imageLoading || !input.trim()}
            title="Generate image"
          >
            🖼️
          </button>

          {loading || imageLoading ? (
            <button
              type="button"
              onClick={stopResponse}
              title="Stop response"
              style={{ background: "#ff4d4d", color: "#fff" }}
            >
              🛑
            </button>
          ) : (
            <button
              type="submit"
              disabled={!input.trim()}
              title="Send message"
            >
              ↑
            </button>
          )}
        </form>

        <div className="notice">
          AI can make mistakes. Check important information.
        </div>
      </section>
    </main>
  );
}